mkdir -p /tmp/scratch && cat > /tmp/scratch/Probe.java <<'EOF'
import org.apache.commons.lang3.text.ExtendedMessageFormat;
import org.apache.commons.lang3.text.FormatFactory;
import java.text.Format;
import java.text.FieldPosition;
import java.text.ParsePosition;
import java.util.*;

public class Probe {
    static class UpperCaseFormat extends Format {
        public StringBuffer format(Object obj, StringBuffer sb, FieldPosition pos) {
            return sb.append(String.valueOf(obj).toUpperCase(Locale.ROOT));
        }
        public Object parseObject(String source, ParsePosition pos) { return source; }
    }
    static class UpperCaseFormatFactory implements FormatFactory {
        public Format getFormat(String name, String args, Locale locale) {
            return new UpperCaseFormat();
        }
    }
    public static void main(String[] args) throws Exception {
        Map<String, FormatFactory> registry = new HashMap<String, FormatFactory>();
        registry.put("upper", new UpperCaseFormatFactory());
        try {
            ExtendedMessageFormat emf = new ExtendedMessageFormat("{0, upper }", registry);
            System.out.println("toPattern=" + emf.toPattern());
            System.out.println("format=" + emf.format(new Object[]{"abc"}));
        } catch (Exception e) {
            System.out.println("Exception: " + e);
        }
    }
}
EOF
CP="target/classes"
javac -cp "$CP" -d /tmp/scratch /tmp/scratch/Probe.java 2>&1 | tail -30
java -cp "$CP:/tmp/scratch" Probe

